function nativeOrderPictures(p){return new Promise(async(resolve,reject)=>{try{const bridge=window.IMCOrderShare;if(!bridge)throw Error('افتح الإدارة داخل تطبيق أندرويد');const images=[];for(const file of p.files){if(file.size>1024*1024)throw Error('صفحة الصور أكبر من الحد المسموح');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));images.push(btoa(binary));}const id=crypto.randomUUID(),timer=setTimeout(()=>reject(Error('انتهت مهلة تجهيز واتساب')),45000);bridge.onmessage=event=>{try{const result=JSON.parse(event.data);if(result.id!==id)return;clearTimeout(timer);if(result.error)reject(Error(result.error));else resolve(result.value);}catch{}};bridge.postMessage(JSON.stringify({id,op:'orderPictures',orderId:p.orderId,images}));}catch(e){reject(e);}});}
import{compressImage}from'./image-upload.mjs';
