let productDrag,productOrderSaving=false;
function clearProductDrag(){document.querySelectorAll('.sort-dragging,.sort-target').forEach(el=>el.classList.remove('sort-dragging','sort-target'));productDrag=undefined;}
document.addEventListener('pointerdown',e=>{const handle=e.target.closest('.product-drag-handle');if(!handle||productOrderSaving||mode!=='admin'||e.button!==0)return;const card=handle.closest('[data-sort-product]');productDrag={id:card.dataset.sortProduct,merchantId:selectedMerchant,pointerId:e.pointerId};handle.setPointerCapture(e.pointerId);card.classList.add('sort-dragging');e.preventDefault();});
document.addEventListener('pointermove',e=>{if(!productDrag||e.pointerId!==productDrag.pointerId)return;document.querySelectorAll('.sort-target').forEach(el=>el.classList.remove('sort-target'));document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-sort-product]')?.classList.add('sort-target');const distance=45;if(e.clientY<distance)window.scrollBy(0,-18);else if(e.clientY>innerHeight-distance)window.scrollBy(0,18);});
document.addEventListener('pointercancel',clearProductDrag);
document.addEventListener('pointerup',async e=>{if(!productDrag||e.pointerId!==productDrag.pointerId)return;const from=productDrag,target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-sort-product]')?.dataset.sortProduct;clearProductDrag();if(!target||target===from.id||from.merchantId!==selectedMerchant)return;const ids=orderedProducts(state.products.filter(p=>p.merchantId===from.merchantId)).map(p=>p.id);productOrderSaving=true;try{await ensureCloud();await business('productReorder',{merchantId:from.merchantId,productIds:moveProduct(ids,from.id,target)});await syncCloud();render();toast('تم حفظ ترتيب المنتجات');}catch(error){toast(error.message);}finally{productOrderSaving=false;}});
